const items = $input.all();

const RSS_SOURCE_CONFIGS = [
  {
    matchDomains: ["theverge.com"],
    name: "The Verge RSS",
    quality: 88,
    signalType: "RSS",
  },
];

function cleanText(value) {
  if (value === null || value === undefined) return "";

  return String(value)
    .replace(/<[^>]*>/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&quot;/g, "\"")
    .replace(/&#39;/g, "'")
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizeId(value) {
  return cleanText(value)
    .toLowerCase()
    .replace(/^https?:\/\//, "")
    .replace(/^www\./, "")
    .replace(/_/g, "-")
    .replace(/[^a-z0-9-]/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 80);
}

function getSourceUrl(input) {
  const candidates = [
    input.link,
    input.url,
    input.guid,
    input.id,
    input.enclosure?.url,
  ];

  const found = candidates
    .map((value) => cleanText(value))
    .find((value) => value.startsWith("http"));

  return found || "";
}

function getPublishedAt(input) {
  return cleanText(
    input.isoDate ||
    input.pubDate ||
    input.published ||
    input.updated ||
    input.date ||
    ""
  );
}

function getTitle(input) {
  return cleanText(
    input.title ||
    input.name ||
    input.headline ||
    "Unbenanntes RSS-Signal"
  );
}

function getDescription(input, title) {
  return cleanText(
    input.contentSnippet ||
    input.summary ||
    input.description ||
    input.content ||
    input["content:encoded"] ||
    input.text ||
    title
  );
}

function getSourceName(sourceUrl, input) {
  const directSource = cleanText(
    input.sourceName ||
    input.source ||
    input.feedTitle ||
    input.creator ||
    input.author ||
    ""
  );

  const lowerUrl = sourceUrl.toLowerCase();

  const matched = RSS_SOURCE_CONFIGS.find((config) =>
    config.matchDomains.some((domain) => lowerUrl.includes(domain))
  );

  if (matched) return matched.name;

  if (directSource) return directSource;

  try {
    if (sourceUrl) {
      const url = new URL(sourceUrl);
      return `${url.hostname.replace(/^www\./, "")} RSS`;
    }
  } catch (error) {
    // Ignore invalid URL.
  }

  return "RSS";
}

function getSourceConfig(sourceName, sourceUrl) {
  const lowerName = sourceName.toLowerCase();
  const lowerUrl = sourceUrl.toLowerCase();

  const matched = RSS_SOURCE_CONFIGS.find((config) =>
    config.name.toLowerCase() === lowerName ||
    config.matchDomains.some((domain) => lowerUrl.includes(domain))
  );

  if (matched) return matched;

  return {
    name: sourceName || "RSS",
    quality: 70,
    signalType: "RSS",
  };
}

function getCategory(title, description, sourceName) {
  const text = `${title} ${description} ${sourceName}`.toLowerCase();

  if (
    text.includes("regulation") ||
    text.includes("regulator") ||
    text.includes("eu ai act") ||
    text.includes("policy") ||
    text.includes("gesetz") ||
    text.includes("compliance")
  ) {
    return "Regulatorische Signale";
  }

  if (
    text.includes("launch") ||
    text.includes("released") ||
    text.includes("introducing") ||
    text.includes("update") ||
    text.includes("tool") ||
    text.includes("app") ||
    text.includes("product")
  ) {
    return "Launches & Tool-Updates";
  }

  if (
    text.includes("agent") ||
    text.includes("agents") ||
    text.includes("agentic") ||
    text.includes("workflow") ||
    text.includes("automation")
  ) {
    return "AI Workflows";
  }

  if (
    text.includes("model") ||
    text.includes("gpt") ||
    text.includes("claude") ||
    text.includes("gemini") ||
    text.includes("openai") ||
    text.includes("anthropic") ||
    text.includes("google deepmind")
  ) {
    return "AI Tools";
  }

  return "AI News";
}

function getScore(title, description, category, sourceConfig) {
  const text = `${title} ${description}`.toLowerCase();

  let score = sourceConfig.quality || 70;

  if (
    text.includes("ai") ||
    text.includes("openai") ||
    text.includes("anthropic") ||
    text.includes("google") ||
    text.includes("microsoft") ||
    text.includes("nvidia") ||
    text.includes("agent") ||
    text.includes("model") ||
    text.includes("tool")
  ) {
    score += 8;
  }

  if (
    category === "Launches & Tool-Updates" ||
    category === "Regulatorische Signale" ||
    category === "AI Workflows"
  ) {
    score += 4;
  }

  return Math.max(1, Math.min(98, Math.round(score)));
}

function getStatus(score) {
  if (score >= 85) return "Hohe Relevanz";
  if (score >= 65) return "Neu";
  return "Beobachten";
}

function getBusinessImpact(category, title) {
  const safeTitle = cleanText(title);

  if (category === "Launches & Tool-Updates") {
    return `Dieses RSS-Signal ist relevant, weil es auf neue Produktfunktionen, Tool-Updates oder marktnahe KI-Entwicklungen hinweist: ${safeTitle}`;
  }

  if (category === "Regulatorische Signale") {
    return `Dieses RSS-Signal ist relevant, weil es auf regulatorische, rechtliche oder Compliance-bezogene Entwicklungen im KI-Umfeld hinweist: ${safeTitle}`;
  }

  if (category === "AI Workflows") {
    return `Dieses RSS-Signal ist relevant, weil es auf neue Automatisierungs- oder Produktivitätsmöglichkeiten mit KI hinweist: ${safeTitle}`;
  }

  if (category === "AI Tools") {
    return `Dieses RSS-Signal ist relevant, weil es auf neue KI-Tools, Modelle, Plattformen oder produktnahe Anwendungen hinweist: ${safeTitle}`;
  }

  return `Dieses RSS-Signal ist relevant, weil es ein potenzielles Markt- oder Technologiesignal im KI-Umfeld enthält: ${safeTitle}`;
}

function getRecommendation(score, category) {
  if (score >= 85) {
    return `Für das Trend-Radar priorisieren und prüfen, ob daraus ein konkreter Use Case im Bereich ${category} entsteht.`;
  }

  if (score >= 65) {
    return `Weiter beobachten und prüfen, ob sich daraus ein relevanter Trend im Bereich ${category} entwickelt.`;
  }

  return `Niedrige Priorität. Nur beobachten, falls sich weitere Signale im Bereich ${category} ergeben.`;
}

const output = [];

for (const item of items) {
  const input = item.json || {};

  const sourceUrl = getSourceUrl(input);
  const publishedAt = getPublishedAt(input);
  const title = getTitle(input);
  const description = getDescription(input, title);
  const sourceName = getSourceName(sourceUrl, input);
  const sourceConfig = getSourceConfig(sourceName, sourceUrl);
  const category = getCategory(title, description, sourceName);
  const score = getScore(title, description, category, sourceConfig);
  const status = getStatus(score);

  const idBase = sourceUrl || input.guid || input.id || title;
  const id = normalizeId(idBase);

  if (!id || !title) {
    continue;
  }

  output.push({
    json: {
      id,
      name: title,
      category,
      status,
      score,
      businessImpact: getBusinessImpact(category, title),
      summary: (description || title).slice(0, 500),
      recommendation: getRecommendation(score, category),
      source: sourceConfig.name,
      timeframe: publishedAt ? "RSS Update" : "Unbekannt",
      signalType: sourceConfig.signalType,

      sourceUrl,
      publishedAt,
      articleTitle: title,
      articleSummary: (description || title).slice(0, 800),
      articleBody: description || title,
      sourceName: sourceConfig.name,
    },
  });
}

return output;

const items = $input.all();

function cleanText(value) {
  if (value === null || value === undefined) return "";

  return String(value)
    .replace(/<[^>]*>/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&quot;/g, "\"")
    .replace(/&#39;/g, "'")
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/\s+/g, " ")
    .trim();
}

function cleanNumber(value, fallback = 0) {
  const number = Number(value);
  if (Number.isFinite(number)) return number;
  return fallback;
}

function normalizeScore(value) {
  return Math.max(0, Math.min(100, cleanNumber(value, 0)));
}

function normalizeId(value) {
  const cleaned = cleanText(value);

  if (!cleaned) return "";

  return cleaned
    .toLowerCase()
    .replace(/_/g, "-")
    .replace(/[^a-z0-9-]/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 80);
}

const output = [];

for (const item of items) {
  const input = item.json || {};

  const normalized = {
    id: normalizeId(input.id || input.sourceUrl || input.name),
    name: cleanText(input.name || "Unbenannter Trend"),
    category: cleanText(input.category || "AI News"),
    status: cleanText(input.status || "Neu"),
    score: normalizeScore(input.score),
    businessImpact: cleanText(input.businessImpact || ""),
    summary: cleanText(input.summary || ""),
    recommendation: cleanText(input.recommendation || ""),
    source: cleanText(input.source || input.sourceName || ""),
    timeframe: cleanText(input.timeframe || ""),
    signalType: cleanText(input.signalType || "RSS"),

    sourceUrl: cleanText(input.sourceUrl || ""),
    publishedAt: cleanText(input.publishedAt || ""),
    articleTitle: cleanText(input.articleTitle || input.name || ""),
    articleSummary: cleanText(input.articleSummary || input.summary || ""),
    articleBody: cleanText(input.articleBody || input.summary || ""),
    sourceName: cleanText(input.sourceName || input.source || ""),
  };

  if (!normalized.id || !normalized.name) {
    continue;
  }

  output.push({
    json: normalized,
  });
}

return output;

const candidates = $("Trend-Daten normalisieren").all();
const existingRows = $("Bestehende Trends lesen").all();

const existingIds = new Set(
  existingRows
    .map((item) => String(item.json.id || "").trim())
    .filter(Boolean)
);

const newTrends = candidates.filter((item) => {
  const id = String(item.json.id || "").trim();
  return id && !existingIds.has(id);
});

return newTrends;

const items = $input.all();

const SOURCE_CONFIGS = [
  {
    matchNames: ["OpenAI"],
    name: "YouTube – OpenAI",
    quality: 100,
    signalType: "YouTube",
    maxItems: 5,
  },
  {
    matchNames: ["Google DeepMind", "DeepMind"],
    name: "YouTube – Google DeepMind",
    quality: 98,
    signalType: "YouTube",
    maxItems: 5,
  },
  {
    matchNames: ["NVIDIA Developer", "NVIDIA"],
    name: "YouTube – NVIDIA Developer",
    quality: 92,
    signalType: "YouTube",
    maxItems: 5,
  },
  {
    matchNames: ["Everlast AI"],
    name: "YouTube – Everlast AI",
    quality: 82,
    signalType: "YouTube",
    maxItems: 5,
  },
  {
    matchNames: ["Christoph Magnussen"],
    name: "YouTube – Christoph Magnussen",
    quality: 78,
    signalType: "YouTube",
    maxItems: 5,
  },
  {
    matchNames: ["Niklas Steenfatt"],
    name: "YouTube – Niklas Steenfatt",
    quality: 76,
    signalType: "YouTube",
    maxItems: 5,
  },
];

function cleanText(value) {
  if (value === null || value === undefined) return "";

  return String(value)
    .replace(/<[^>]*>/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&quot;/g, "\"")
    .replace(/&#39;/g, "'")
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizeId(value) {
  return cleanText(value)
    .replace(/^yt:video:/i, "")
    .toLowerCase()
    .replace(/_/g, "-")
    .replace(/[^a-z0-9-]/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 80);
}

function asArray(value) {
  if (!value) return [];
  return Array.isArray(value) ? value : [value];
}

function getFeedTitle(feed) {
  return cleanText(
    feed?.title ||
    feed?.author?.name ||
    feed?.["media:title"] ||
    ""
  );
}

function getSourceConfig(feed) {
  const feedTitle = getFeedTitle(feed).toLowerCase();
  const authorName = cleanText(feed?.author?.name).toLowerCase();

  const found = SOURCE_CONFIGS.find((config) =>
    config.matchNames.some((name) => {
      const needle = name.toLowerCase();
      return feedTitle.includes(needle) || authorName.includes(needle);
    })
  );

  if (found) return found;

  const fallbackName = getFeedTitle(feed) || "Unknown";

  return {
    matchNames: [fallbackName],
    name: `YouTube – ${fallbackName}`,
    quality: 70,
    signalType: "YouTube",
    maxItems: 5,
  };
}

function getEntryLink(entry, videoId) {
  const link = entry?.link;

  if (typeof link === "string" && link.trim()) {
    return cleanText(link);
  }

  if (link?.href) {
    return cleanText(link.href);
  }

  if (Array.isArray(link)) {
    const alternate = link.find((item) => item?.rel === "alternate" && item?.href);
    if (alternate?.href) return cleanText(alternate.href);

    const firstWithHref = link.find((item) => item?.href);
    if (firstWithHref?.href) return cleanText(firstWithHref.href);
  }

  if (videoId) {
    return `https://www.youtube.com/watch?v=${videoId}`;
  }

  return "";
}

function getVideoId(entry) {
  const directId =
    entry?.["yt:videoId"] ||
    entry?.videoId ||
    entry?.id ||
    "";

  const cleaned = cleanText(directId).replace(/^yt:video:/i, "");

  if (cleaned) return cleaned;

  const url = getEntryLink(entry, "");
  const watchMatch = url.match(/[?&]v=([^&]+)/);
  if (watchMatch?.[1]) return watchMatch[1];

  const shortsMatch = url.match(/\/shorts\/([^/?]+)/);
  if (shortsMatch?.[1]) return shortsMatch[1];

  return "";
}

function getTitle(entry) {
  return cleanText(
    entry?.title ||
    entry?.["media:group"]?.["media:title"] ||
    entry?.["media:title"] ||
    "Unbenanntes YouTube-Signal"
  );
}

function getDescription(entry, title) {
  return cleanText(
    entry?.["media:group"]?.["media:description"] ||
    entry?.["media:description"] ||
    entry?.description ||
    entry?.summary ||
    title
  );
}

function getPublishedAt(entry) {
  return cleanText(
    entry?.published ||
    entry?.pubDate ||
    entry?.isoDate ||
    entry?.updated ||
    ""
  );
}

function getCategory(title, description, sourceConfig) {
  const text = `${title} ${description} ${sourceConfig.name}`.toLowerCase();

  if (
    text.includes("gpu") ||
    text.includes("nvidia") ||
    text.includes("cuda") ||
    text.includes("dgx") ||
    text.includes("jax") ||
    text.includes("kernel") ||
    text.includes("infrastructure") ||
    text.includes("rechenleistung") ||
    text.includes("developer")
  ) {
    return "AI Infrastructure";
  }

  if (
    text.includes("workflow") ||
    text.includes("workflows") ||
    text.includes("agentic") ||
    text.includes("agent") ||
    text.includes("agents") ||
    text.includes("automation") ||
    text.includes("automatisierung") ||
    text.includes("produktivität")
  ) {
    return "AI Workflows";
  }

  if (
    text.includes("research") ||
    text.includes("forschung") ||
    text.includes("benchmark") ||
    text.includes("eval") ||
    text.includes("safety") ||
    text.includes("alignment") ||
    text.includes("model") ||
    text.includes("gpt") ||
    text.includes("claude") ||
    text.includes("gemini") ||
    text.includes("gemma")
  ) {
    return "AI Research";
  }

  if (
    text.includes("demo") ||
    text.includes("introducing") ||
    text.includes("launch") ||
    text.includes("update") ||
    text.includes("app") ||
    text.includes("tool")
  ) {
    return "AI Product Demo";
  }

  return "AI Tools";
}

function getScore(title, description, category, sourceConfig) {
  const text = `${title} ${description}`.toLowerCase();

  let score = sourceConfig.quality || 70;

  if (
    text.includes("agent") ||
    text.includes("agents") ||
    text.includes("agentic") ||
    text.includes("workflow") ||
    text.includes("codex") ||
    text.includes("gpt") ||
    text.includes("claude") ||
    text.includes("gemini") ||
    text.includes("gemma") ||
    text.includes("developer") ||
    text.includes("api")
  ) {
    score += 8;
  }

  if (
    category === "AI Infrastructure" ||
    category === "AI Tools" ||
    category === "AI Workflows"
  ) {
    score += 4;
  }

  return Math.max(1, Math.min(98, Math.round(score)));
}

function getStatus(score) {
  if (score >= 85) return "Hohe Relevanz";
  if (score >= 65) return "Neu";
  return "Beobachten";
}

function getBusinessImpact(category, title) {
  const safeTitle = cleanText(title);

  if (category === "AI Infrastructure") {
    return `Dieses YouTube-Signal ist für AI Infrastructure relevant, weil es auf KI-Infrastruktur, GPUs, Developer-Tools, Rechenleistung oder technische Grundlagen für KI-Systeme hinweist: ${safeTitle}`;
  }

  if (category === "AI Workflows") {
    return `Dieses YouTube-Signal ist für AI Workflows relevant, weil es auf neue Automatisierungs- oder Produktivitätsmöglichkeiten mit KI hinweist: ${safeTitle}`;
  }

  if (category === "AI Research") {
    return `Dieses YouTube-Signal ist für AI Research relevant, weil es Hinweise auf neue Modelle, Forschungsergebnisse, Sicherheitsfragen oder technische Fortschritte liefert: ${safeTitle}`;
  }

  if (category === "AI Product Demo") {
    return `Dieses YouTube-Signal ist für AI Product Demo relevant, weil es offizielle Produktfunktionen, Demos oder neue Anwendungsmöglichkeiten sichtbar macht: ${safeTitle}`;
  }

  return `Dieses YouTube-Signal ist für AI Tools relevant, weil es auf neue Funktionen, Entwicklerwerkzeuge, Agenten oder produktnahe KI-Anwendungen hinweist: ${safeTitle}`;
}

function getRecommendation(score, category) {
  if (score >= 85) {
    return `Für das Trend-Radar priorisieren und prüfen, ob daraus ein konkreter Use Case im Bereich ${category} entsteht.`;
  }

  if (score >= 65) {
    return `Weiter beobachten und prüfen, ob sich daraus ein relevanter Trend im Bereich ${category} entwickelt.`;
  }

  return `Niedrige Priorität. Nur beobachten, falls sich weitere Signale im Bereich ${category} ergeben.`;
}

const output = [];

for (const item of items) {
  const feed = item.json?.feed || item.json;
  const sourceConfig = getSourceConfig(feed);

  const entries = asArray(feed?.entry).slice(0, sourceConfig.maxItems || 5);

  for (const entry of entries) {
    const videoId = getVideoId(entry);
    const id = normalizeId(videoId || entry?.id || entry?.title);

    if (!id) continue;

    const title = getTitle(entry);
    const description = getDescription(entry, title);
    const published = getPublishedAt(entry);
    const sourceUrl = getEntryLink(entry, videoId);
    const category = getCategory(title, description, sourceConfig);
    const score = getScore(title, description, category, sourceConfig);
    const status = getStatus(score);

    output.push({
      json: {
        id,
        name: title,
        category,
        status,
        score,
        businessImpact: getBusinessImpact(category, title),
        summary: (description || title).slice(0, 500),
        recommendation: getRecommendation(score, category),
        source: sourceConfig.name,
        timeframe: published ? "YouTube Upload" : "Unbekannt",
        signalType: sourceConfig.signalType,

        sourceUrl,
        publishedAt: published,
        articleTitle: title,
        articleSummary: (description || title).slice(0, 800),
        articleBody: description || title,
        sourceName: sourceConfig.name,
      },
    });
  }
}

return output;
